CREATE TABLE attachments(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES companies(id),document_id INTEGER NOT NULL REFERENCES documents(id),kind TEXT NOT NULL CHECK(kind IN ('invoice','delivery_note','other')),sha256 TEXT NOT NULL,storage_path TEXT NOT NULL,original_filename TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'local',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(company_id,document_id,kind,sha256));
CREATE TRIGGER attachment_company_insert BEFORE INSERT ON attachments WHEN NOT EXISTS(SELECT 1 FROM documents WHERE id=NEW.document_id AND company_id=NEW.company_id) BEGIN SELECT RAISE(ABORT,'attachment company mismatch'); END;
CREATE TABLE aade_settings(company_id INTEGER PRIMARY KEY REFERENCES companies(id),environment TEXT NOT NULL CHECK(environment IN ('test','production')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rpa_jobs(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES companies(id),mode TEXT NOT NULL CHECK(mode IN ('simulation','fill_only')),status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rpa_items(id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL REFERENCES rpa_jobs(id),document_id INTEGER NOT NULL REFERENCES documents(id),payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',reason TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(job_id,document_id));
CREATE INDEX rpa_document ON rpa_items(document_id,status);
